"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["81922"],{24865(e){e.exports=JSON.parse('{"id":"F432","slug":"triangular-arbitrage","name":"Cross Rates and Triangular Arbitrage","subject":"International Finance","section":"Global Finance","topic":"Foreign exchange market structure","level":"Intermediate","aliases":["foreign exchange market structure","bid ask spread in pips","three currency arbitrage","implied cross rate"],"formula":{"latex":"X_{EUR/JPY}=X_{EUR/USD}\\\\times X_{USD/JPY},\\\\quad \\\\text{Pips}=\\\\frac{Ask-Bid}{0.0001}","also":[],"text":"Implied cross rate = EUR/USD rate x USD/JPY rate. Triangular arbitrage trades around the three currencies at the dealer\'s prices (buy at the ask, sell at the bid) and profits if the quoted cross differs from the implied cross by more than the spread; Spread in pips = (ask - bid) / pip size"},"symbols":[{"symbol":"Bid","meaning":"Price at which a dealer buys the base currency from you","unit":"rate"},{"symbol":"Ask","meaning":"Price at which a dealer sells the base currency to you","unit":"rate"},{"symbol":"Pip","meaning":"Smallest standard price move: 0.0001 for most pairs, 0.01 for yen pairs","unit":"rate"}],"when_to_use":"Use it to see how the three prices in a currency triangle stay in line. Dealers quote a bid and ask, so you always buy dearer and sell cheaper, and the gap is their spread and your trading cost. Arbitrage profits are tiny and vanish quickly in liquid markets, and a profit only exists if it exceeds the spreads, which is what the calculator tests.","worked_example":{"problem":"Quotes (bid/ask): EUR/USD 1.0850/1.0852, USD/JPY 150.20/150.22, EUR/JPY 162.90/163.10. Start with 1,000,000 USD and test both directions.","inputs":{"eb":1.085,"ea":1.0852,"jb":150.2,"ja":150.22,"xb":162.9,"xa":163.1,"u":1000000},"steps":[{"label":"EUR/USD spread in pips","working":"(1.0852-1.085) / 0.0001","value":"2.0"},{"label":"Implied EUR/JPY bid = EUR/USD bid x USD/JPY bid","working":"1.085 x 150.2","value":"162.967"},{"label":"Implied EUR/JPY ask = EUR/USD ask x USD/JPY ask","working":"1.0852 x 150.22","value":"163.019"},{"label":"Loop A: USD to EUR (at the ask), to JPY (at the bid), back to USD (at the ask)","working":"1,000,000 / 1.0852 x 162.9 / 150.22","value":"999,271.59"},{"label":"Profit, loop A","working":"999272-1,000,000","value":"-728.41"},{"label":"Loop B: USD to JPY (bid), to EUR (at the ask), back to USD (bid)","working":"1,000,000 x 150.2 / 163.1 x 1.085","value":"999,184.55"},{"label":"Profit, loop B","working":"999185-1,000,000","value":"-815.45"}],"answer":"The EUR/USD spread is 2.0 pips. The implied EUR/JPY cross is 162.967 bid and 163.019 ask against the quoted 162.90/163.10. Going USD to EUR to JPY to USD ends with 999,271.59, a result of -728.41; going USD to JPY to EUR to USD ends with 999,184.55, a result of -815.45. A positive number is a profit; here neither loop earns one after the spreads."},"calculator":{"available":true,"inputs":[{"id":"eb","label":"EUR/USD bid","unit":"","type":"number","default":1.085,"hint":""},{"id":"ea","label":"EUR/USD ask","unit":"","type":"number","default":1.0852,"hint":""},{"id":"jb","label":"USD/JPY bid","unit":"","type":"number","default":150.2,"hint":""},{"id":"ja","label":"USD/JPY ask","unit":"","type":"number","default":150.22,"hint":""},{"id":"xb","label":"EUR/JPY bid","unit":"","type":"number","default":162.9,"hint":""},{"id":"xa","label":"EUR/JPY ask","unit":"","type":"number","default":163.1,"hint":""},{"id":"u","label":"Starting USD","unit":"money","type":"number","default":1000000,"hint":""}],"checks":[{"expr":"ea>=eb and ja>=jb and xa>=xb and eb>0 and jb>0 and xb>0","message":"Each ask must be at least the bid, and all rates must be above zero."}],"steps":[{"id":"pips","label":"EUR/USD spread in pips","expr":"(ea-eb)/0.0001","format":"num1"},{"id":"cb","label":"Implied EUR/JPY bid = EUR/USD bid x USD/JPY bid","expr":"eb*jb","format":"num3"},{"id":"ca","label":"Implied EUR/JPY ask = EUR/USD ask x USD/JPY ask","expr":"ea*ja","format":"num3"},{"id":"a_","label":"Loop A: USD to EUR (at the ask), to JPY (at the bid), back to USD (at the ask)","expr":"u/ea*xb/ja","format":"money"},{"id":"pa","label":"Profit, loop A","expr":"a_-u","format":"money"},{"id":"b_","label":"Loop B: USD to JPY (bid), to EUR (at the ask), back to USD (bid)","expr":"u*jb/xa*eb","format":"money"},{"id":"pb","label":"Profit, loop B","expr":"b_-u","format":"money"}],"results":["pips","pa","pb"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"pips":2,"cb":162.96699999999998,"ca":163.018744,"a_":999271.5929647944,"pa":-728.4070352056297,"b_":999184.5493562232,"pb":-815.4506437767996}},"finder":{"finds":"Whether three currency quotes are consistent","needs":"Bid and ask for three currency pairs"},"related":[{"slug":"fx-forward-points","name":"Forward Exchange Rate and Forward Points"},{"slug":"cross-border-payment-cost","name":"Cross-Border Payment All-In Cost"},{"slug":"bid-ask-spread","name":"Bid-Ask Spread and Trading Cost"}],"related_ids":["F433","F364","F261"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>X</mi><mrow><mi>E</mi><mi>U</mi><mi>R</mi><mi mathvariant=\\"normal\\">/</mi><mi>J</mi><mi>P</mi><mi>Y</mi></mrow></msub><mo>=</mo><msub><mi>X</mi><mrow><mi>E</mi><mi>U</mi><mi>R</mi><mi mathvariant=\\"normal\\">/</mi><mi>U</mi><mi>S</mi><mi>D</mi></mrow></msub><mo>\xd7</mo><msub><mi>X</mi><mrow><mi>U</mi><mi>S</mi><mi>D</mi><mi mathvariant=\\"normal\\">/</mi><mi>J</mi><mi>P</mi><mi>Y</mi></mrow></msub><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Pips</mtext><mo>=</mo><mfrac><mrow><mi>A</mi><mi>s</mi><mi>k</mi><mo>\u2212</mo><mi>B</mi><mi>i</mi><mi>d</mi></mrow><mn>0.0001</mn></mfrac></mrow><annotation encoding=\\"application/x-tex\\">X_{EUR/JPY}=X_{EUR/USD}\\\\times X_{USD/JPY},\\\\quad \\\\text{Pips}=\\\\frac{Ask-Bid}{0.0001}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"cva-approximation","name":"Credit Valuation Adjustment (CVA)"},"next":{"slug":"cross-border-payment-cost","name":"Cross-Border Payment All-In Cost"},"lesson":null,"total":522}')}}]);